/**
 * `repr()` for Python's `float` and the `float(str)` constructor.
 *
 * Floats are plain JavaScript numbers throughout this port; the only thing that
 * needs porting is the textual shape, which differs from `Number.prototype
 * .toString()` in three ways: integral values keep a `.0`, the switch to
 * exponential notation happens at different magnitudes, and exponents are
 * zero-padded to two digits.
 */

import { PyConversionError } from './pyerrors.mjs';
import {
  isAsciiSpace,
  transformDecimalAndSpaceToAscii,
} from './pyunicode.mjs';

/**
 * Shortest decimal digit string that round-trips to `value`, plus the decimal
 * exponent of its leading digit.  `Number.prototype.toExponential()` with no
 * argument is specified to produce exactly those digits.
 */
function shortestDigits(value) {
  let text = value.toExponential();
  if (Number(text) !== value) {
    // Defensive: fall back to a widening search if a host ever deviates from
    // the shortest-round-trip requirement.
    for (let precision = 0; precision <= 17; precision += 1) {
      const candidate = value.toExponential(precision);
      if (Number(candidate) === value) {
        text = candidate;
        break;
      }
    }
  }
  const [mantissa, exponent] = text.split('e');
  const digits = mantissa.replace('.', '').replace('-', '');
  return { digits, exp10: Number(exponent) };
}

/**
 * `float.__repr__()` — CPython's `'r'` format code: shortest round-trip digits,
 * exponential notation when the decimal point lands at or before position -4 or
 * past position 16, and a mandatory trailing `.0` otherwise.
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const magnitude = Math.abs(value);

  let digits = '0';
  let decpt = 1;
  if (magnitude !== 0) {
    const shortest = shortestDigits(magnitude);
    digits = shortest.digits;
    decpt = shortest.exp10 + 1;
  }

  let body;
  if (decpt <= -4 || decpt > 16) {
    const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits[0];
    const exponent = decpt - 1;
    const sign = exponent < 0 ? '-' : '+';
    body = `${mantissa}e${sign}${String(Math.abs(exponent)).padStart(2, '0')}`;
  } else if (decpt <= 0) {
    body = `0.${'0'.repeat(-decpt)}${digits}`;
  } else if (decpt >= digits.length) {
    body = `${digits}${'0'.repeat(decpt - digits.length)}.0`;
  } else {
    body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
  }

  return negative ? `-${body}` : body;
}

/**
 * Strip the underscores PEP 515 allows, rejecting any that is not sandwiched
 * between two ASCII digits.  Mirrors
 * `_Py_string_to_number_with_underscores()`.
 */
function stripUnderscores(text) {
  if (!text.includes('_')) return text;
  const isDigit = (ch) => ch !== undefined && ch >= '0' && ch <= '9';
  let out = '';
  let prev = '';
  for (const ch of text) {
    if (ch === '_') {
      if (!isDigit(prev)) return null;
    } else {
      if (prev === '_' && !isDigit(ch)) return null;
      out += ch;
    }
    prev = ch;
  }
  return prev === '_' ? null : out;
}

/** Trim the whitespace `Py_ISSPACE()` recognises from both ends. */
function stripAsciiSpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isAsciiSpace(text[start])) start += 1;
  while (end > start && isAsciiSpace(text[end - 1])) end -= 1;
  return text.slice(start, end);
}

const DECIMAL_FLOAT = /^(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][-+]?[0-9]+)?$/;

/**
 * `float(str)`.
 *
 * Accepts an optional sign followed by either a decimal literal or one of
 * `inf` / `infinity` / `nan` (any case), surrounded by optional whitespace,
 * with PEP 515 underscores permitted between digits.
 */
export function pyFloatFromString(text) {
  const folded = transformDecimalAndSpaceToAscii(text);
  const unscored = stripUnderscores(folded);
  if (unscored === null) throw new PyConversionError('could not convert string to float');

  let body = stripAsciiSpace(unscored);
  let sign = 1;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    sign = -1;
    body = body.slice(1);
  }

  const lowered = body.toLowerCase();
  if (lowered === 'inf' || lowered === 'infinity') return sign * Infinity;
  if (lowered === 'nan') return NaN;

  if (!DECIMAL_FLOAT.test(body)) {
    throw new PyConversionError('could not convert string to float');
  }
  return sign * Number(body);
}

#!/usr/bin/env node
/* Differential harness: run a case list through both implementations. */
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const REF = '/workspace/dataset/test10_executable';
const CASES = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const showAll = process.argv.includes('--all');

// Strip the PyInstaller notice (contains a PID) and normalise nothing else.
function norm(s) {
  return s.replace(/^\[PYI-\d+:ERROR\].*$/gm, '[PYI:ERROR]');
}

let pass = 0;
const fails = [];
for (const args of CASES) {
  const a = spawnSync(REF, args, { encoding: 'buffer', env: { ...process.env, COLUMNS: undefined } });
  const b = spawnSync('node', ['/output/test10.mjs', ...args], { encoding: 'buffer' });
  const ao = a.stdout.toString('binary'), bo = b.stdout.toString('binary');
  const ae = norm(a.stderr.toString('binary')), be = norm(b.stderr.toString('binary'));
  const ok = ao === bo && ae === be && a.status === b.status;
  if (ok) pass++;
  else fails.push({ args, py: { out: ao, err: ae, rc: a.status }, js: { out: bo, err: be, rc: b.status } });
}

console.log(`PASS ${pass}/${CASES.length}`);
for (const f of (showAll ? fails : fails.slice(0, 25))) {
  console.log('--- ARGS', JSON.stringify(f.args));
  if (f.py.out !== f.js.out) { console.log('  PY.out', JSON.stringify(f.py.out)); console.log('  JS.out', JSON.stringify(f.js.out)); }
  if (f.py.err !== f.js.err) { console.log('  PY.err', JSON.stringify(f.py.err)); console.log('  JS.err', JSON.stringify(f.js.err)); }
  if (f.py.rc !== f.js.rc) console.log('  RC', f.py.rc, 'vs', f.js.rc);
}
if (fails.length > 25 && !showAll) console.log(`... ${fails.length - 25} more failures`);
process.exitCode = fails.length ? 1 : 0;
