const buf = new ArrayBuffer(8);
const dv = new DataView(buf);

function bitsOf(x) { dv.setFloat64(0, x); return dv.getBigUint64(0); }
function fromBits(b) { dv.setBigUint64(0, b & 0xffffffffffffffffn); return dv.getFloat64(0); }

// next representable double away from zero / toward zero (finite, non-nan)
