  if (Number.isNaN(x) || x === -Infinity) return x;
  if (x === 0) return fromBits(0x8000000000000001n);
  let b = bitsOf(x);
  if (x > 0) b -= 1n; else b += 1n;
  return fromBits(b);
}

// Exact decimal string of N * 2^K (N BigInt >= 0, K int)
function scaledToDecimal(N, K) {
  if (N === 0n) return '0';
  if (K >= 0) return (N << BigInt(K)).toString();
  const s = -K;
  const num = N * (5n ** BigInt(s));
  let str = num.toString();
  if (str.length <= s) str = '0'.repeat(s - str.length + 1) + str;
  const ip = str.slice(0, str.length - s);
  const fp = str.slice(str.length - s).replace(/0+$/, '');
  return fp.length ? `${ip}.${fp}` : ip;
