// Decompose |x| into { M: BigInt, E: int } with |x| = M * 2^E
function decompose(x) {
  const b = bitsOf(Math.abs(x));
  const expField = Number((b >> 52n) & 0x7ffn);
  const frac = b & 0xfffffffffffffn;
  if (expField === 0) return { M: frac, E: -1074 };
  return { M: frac | 0x10000000000000n, E: expField - 1075 };
